// GATE 1: patient identity + final-status validation
const items = $input.all();
const output = [];
for (const item of items) {
  const r = item.json;
  const okPatient = r.patient_id && (r.mrn || r.dob);
  const okFinal = r.result_status === 'final';
  if (okPatient && okFinal) {
    output.push({ json: { ...r, gate1: 'pass' } });
  } else {
    output.push({ json: { ...r, gate1: 'BLOCKED', reason: 'patient mismatch or non-final status' } });
  }
}
return output;

