// STEP 5: provider-approved ICD-10 condition derivation
const items = $input.all();
const lib = { 'heart failure': 'I50.9', 'type 2 diabetes': 'E11.9', 'ckd': 'N18.9', 'hypertension': 'I10', 'iron deficiency anemia': 'D50.9', 'hyperlipidemia': 'E78.5' };
const output = [];
for (const item of items) {
  const j = item.json;
  const approved = (j.provider_conditions || []).map(c => ({ code: lib[c.toLowerCase()] || c, label: c }));
  output.push({ json: { ...j, icd10_tags: approved } });
}
return output;

// STEP 7: append-only audit event
const items = $input.all();
const ts = new Date().toISOString();
return items.map(item => ({ json: {
  event: 'lab_result_finalized',
  patient_id: item.json.patient_id,
  encounter_id: item.json.encounter_id || null,
  actor_role: 'provider',
  action: 'openemr_write|crm_tag',
  timestamp: ts,
  icd10: (item.json.icd10_tags || []).map(t => t.code),
  result_status: 'final'
}});
